List<String> strings = new ArrayList<>();
List<Integer> ints = new ArrayList<>();

// Both are the exact same class at runtime — erasure
System.out.println(strings.getClass() == ints.getClass()); // true

// Doesn't compile: can't check a parameterized type at runtime
// if (strings instanceof List<String>) {}

// Compiles, but only checks the raw type
if (strings instanceof List<?>) {
    System.out.println("it's some kind of List");
}

// Producer: reading works, adding doesn't (except null)
void printAll(List<? extends Number> producer) {
    for (Number n : producer) System.out.println(n);
    // producer.add(1); // doesn't compile — unsafe
}
printAll(List.of(1, 2, 3));       // List<Integer> accepted
printAll(List.of(1.5, 2.5));      // List<Double> accepted too

// Consumer: writing works, reading only gives Object
void addIntegers(List<? super Integer> consumer) {
    consumer.add(1);
    consumer.add(2);
}
List<Number> numbers = new ArrayList<>();
addIntegers(numbers); // List<Number> accepts Integers written into it

// Unbounded — can't compare T values, only use Object methods
static <T> T firstOf(List<T> list) { return list.get(0); }

// Bounded — the compiler now knows T is Comparable<T>
static <T extends Comparable<T>> T max(List<T> list) {
    T best = list.get(0);
    for (T item : list) {
        if (item.compareTo(best) > 0) best = item; // compareTo available!
    }
    return best;
}

max(List.of(3, 1, 4, 1, 5)); // 5 — Integer implements Comparable<Integer>
